     "ex": "const cities = [\"Cairo\", \"Giza\", \"Alexandria\"];\nconsole.log(cities[0], cities[2], cities.at(-1));\nconsole.log(\"count:\", cities.length);\nconsole.log(cities[10]);   // undefined, not an error\nconst empty = [];\nconsole.log(empty.length, Array.isArray(empty));",
